#%%
# We observe 0 <= A_i < X_i <= (A_i + 1)
# where A_i has the random phase phi_i
# phi_i is independent of X_i, so learning it doesn't give any info about X_i
# A_i - phi_i is an integer usually in {0, 1, 2}
# so learning A_i only gives us about a bit of info about X_i per observation
#
# We have interval observations of X_i
# We choose to model X_i ~ exp(Y_i)
# where Y_i is normally distributed
# since interval observations of the normal distribution are more tractable
# B_i := log(A_i), C_i := log(A_i + 1)
# so we observe B_i < Y_i < C_i
#
# Algorithm:
# 1. initialize a NIG prior for mu, sigma
# 2. "Responsibility"] Consider the distribution of the latent variable Y_i. The predictive distribution of Y is student-t.
#    and the observation of B_i,C_i truncates this distribution.
#    Evaluate and store the partial integrals of the zeroth, first, and second moments of the predictive distribution.
#    And use this to compute the first and second moments of the truncated distributions.
# 3. "Update"] Update the NIG prior based on the sufficient statistics of the latent distributions.
# 4. Check for convergence. If not, return to step 2.

import numpy as np
from scipy import stats
import matplotlib.pyplot as plt
# # Data
# B = np.array([0,1,2]*100)
# C = B + 1

eps = 1e-6
def run_inference(B, C, *, max_iters=5):
    # 1.
    m0, kappa0, alpha0, beta0 = 0, eps, eps, eps
    m, kappa, alpha, beta = m0, kappa0, alpha0, beta0
    assert max_iters > 0
    for _ in range(max_iters):
        # 2.
        # predictive distro
        student_mu = m
        student_nu = 2*alpha
        student_s2 = (beta / alpha) * (1 + 1/kappa)
        # moments
        ymin, ymax, yres = -10, 10, 1000
        ys = np.linspace(ymin, ymax, yres)
        dy = (ymax - ymin) / (yres - 1)
        # TODO: this (and all moments) could be sped by computing once for the standard student-t
        # and then normalizing B and C according to the current student_distrib
        student_distrib = stats.t(df=student_nu, loc=student_mu, scale=np.sqrt(student_s2))
        student_pdf = student_distrib.pdf(ys)
        moment0 = np.cumsum(student_pdf * dy)
        moment1 = np.cumsum(ys * student_pdf * dy)
        moment2 = np.cumsum(ys**2 * student_pdf * dy)
        # print("numerical moment2:", moment2[-1])
        # print("analytical moment2:", student_distrib.var() + student_distrib.mean()**2)
        B_indices = np.floor((B - ymin) / dy).astype(int)
        B_indices = np.clip(B_indices, 0, yres - 1)
        C_indices = np.floor((C - ymin) / dy).astype(int)
        yi_expected = (moment1[C_indices] - moment1[B_indices]) / (moment0[C_indices] - moment0[B_indices])
        yi2_expected = (moment2[C_indices] - moment2[B_indices]) / (moment0[C_indices] - moment0[B_indices])
        yi_expected = yi_expected.mean()
        yi2_expected = yi2_expected.mean()
        # print("yi_expected:", yi_expected)
        # print("yi2_expected:", yi2_expected)
        # 3.
        kappa_new = kappa0 + len(B)
        m_new = (kappa0 * m0 + len(B) * yi_expected) / kappa_new
        alpha_new = alpha0 + 0.5 * len(B)
        S = (yi2_expected - yi_expected**2) * len(B)
        beta_new = beta0 + 0.5 * S + (kappa0 * len(B)) / (2 * kappa_new) * (yi_expected - m0)**2
        m, kappa, alpha, beta = m_new, kappa_new, alpha_new, beta_new

        # plt.show()
        # print(m, kappa, alpha, beta)
        # plt.plot(ys, student_pdf)
        # plt.vlines([0, 1, 2, 3], 0, 1, color='red', linewidth=.5)
    return student_distrib


