true_distrib = stats.lognorm(s=1, scale=1)
samples = true_distrib.rvs(size=N)
phi_i = stats.uniform(0, 1).rvs(size=N)
# compute C_i by rounding up to the next number with phase phi_i
frac_part, int_part = np.modf(samples)
int_part += frac_part > phi_i  # if we've already missed the phase, we'll need to go to the next period
C = int_part + phi_i
B = np.maximum(0, C - 1)
logB, logC = np.log(B), np.log(C)

